import torch


def run(input):
    return torch.poisson(input)


def gen_inputs(ctx, device):
    import torch
    shape = tuple(ctx["input__shape"])
    dtype = getattr(torch, ctx["input__dtype"])
    inp = torch.rand(shape, dtype=dtype, device=device) * 10 + 1
    return {"input": inp}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    if bool((sol < 0).any().item()):
        return {"passed": False, "message": "poisson output has negative values", "metrics": {}}
    if not bool(torch.isfinite(sol).all().item()):
        return {"passed": False, "message": "poisson output has non-finite values", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
